from taf.hw.channel_emulator import channel_emulator
from taf.hw.vertex.factory import VertexChannelEmulatorFactory


class vertex(channel_emulator):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._factory = VertexChannelEmulatorFactory()
        self._device = None

    def setup(self, model=None, version=None, alias=None, **kwargs):
        """
        connect to channel emulator via ssh and connect to telnet(optional) on port, and register alias
        :param model: str, optional, channel emulator model, e.g. "VCE6"
        :param version: str, optional, channel emulator version, e.g. "0.1"
        :param alias: str, optional, alias name
        :param kwargs: device specific parameters:
                       str host: vertex ip address, default '127.0.0.1'
                       int port: vertex RPI port, default 3000
                       str proxy: proxy ip address, default '127.0.0.1'
                       str proxy_username: proxy username, default 'ute'
                       str proxy_password: proxy password, default 'ute'
                       int timeout: optional, timeout for channel emulator command, default 2s
        :return:
        :exception: connection failed exception
        """
        self._device = self._factory.create(model, version, **kwargs)
        self._device.setup()
        self.configured_emulators.add(self._device, alias)
        return self._device
